    'Customers can add funds to the wallet with an available payment method.' => 'Al habilitar la opción, los clientes podrán agregar fondos a la billetera a través del método de pago disponible.',
    'Customers can browse and search products by brand inside any shop.' => 'Si está habilitado, los clientes pueden ver las marcas y pueden explorar y buscar productos de cada marca dentro de cualquier tienda.',
    'Customers can pay for orders from their wallet balance.' => 'Cuando la función de billetera está habilitada, los clientes pueden usar el saldo de su billetera para pagar los pedidos.',
