    'Customers earn rewards when someone registers with their referral code.' => 'Si está habilitado, los clientes obtendrán recompensas cuando alguien se registre usando su código de referencia.',
    'Customers get a wallet for placing orders and receiving refunds.' => 'Si está habilitada, los clientes pueden tener la opción de billetera en su cuenta y usarla al realizar pedidos y obtener reembolsos.',
    'Customers must reach this amount before they can check out.' => ' esto significa que los clientes deberán agregar suficientes artículos para alcanzar esta cantidad especificada antes de poder realizar el pago.',
    'Customers must verify their email during sign-up.' => 'Si la verificación de correo electrónico está activada, los clientes deben verificar su correo electrónico durante el registro para garantizar un proceso de inicio de sesión seguro.',
    'Customers must verify their phone with an OTP to sign up.' => 'Si la verificación del número de teléfono está activada, los clientes deben verificar su número de teléfono con una OTP para completar el proceso de registro.',
    'Customers pay and instantly download pre-uploaded digital products.' => 'para las entregas de productos listos, los clientes pueden pagar y descargar instantáneamente productos digitales precargados.',
    'Customers pay by wallet, card or internet banking before shipping.' => 'Customers pay by wallet, card or internet banking before shipping.',
    'Customers pay first, then admin uploads the digital products for download.' => 'Para las entregas listas para después de la venta, los clientes pagan primero y luego el administrador carga los productos digitales que quedan disponibles para que los clientes los descarguen.',
    'Customers pay first, then the vendor uploads the digital products for download.' => 'Para las entregas listas para después de la venta, los clientes pagan primero y luego el proveedor carga los productos digitales que quedan disponibles para que los clientes los descarguen.',
    'Customers pay online by wallet, card or internet banking at checkout.' => 'El pago digital permite a los clientes pagar sus pedidos en línea utilizando métodos como billeteras móviles, por ejemplo (bkash, nagad, rocket), tarjetas de crédito, débito o banca por Internet integrada en el sistema cuando se realiza el pedido.',
